package app.rwun;
import android.content.Context;import org.json.*;import java.time.*;import java.util.*;import java.nio.file.*;
public final class RaceHostTest {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}interface Work{void run()throws Exception;}static void bad(Work w,String s){boolean fail=false;try{w.run();}catch(Exception e){fail=true;}ok(fail,s);}
 static RaceTraining.Evidence e(LocalDate date,double km,int effort,int fatigue,boolean reported){return new RaceTraining.Evidence(date,km,Math.round(km*400),effort,fatigue,false,reported);}
 public static void main(String[] args)throws Exception{
  LocalDate today=LocalDate.now();Set<DayOfWeek> days=Set.of(DayOfWeek.TUESDAY,DayOfWeek.THURSDAY,DayOfWeek.SUNDAY);
  var noHistory=RaceTraining.review(List.of(),today,false);ok(noHistory.daysSinceLast()==-1&&noHistory.baseline()==0&&noHistory.factor()==1,"missing history is unknown");
  var old=List.of(e(today.minusDays(35),10,4,2,true));var review=RaceTraining.review(old,today,false);ok(review.factor()==.65&&review.daysSinceLast()==35,"long gap reduces initial baseline");
  ok(RaceTraining.review(List.of(e(today.minusDays(16),8,4,2,true)),today,false).factor()==.8,"two week gap");
  var hard=List.of(e(today.minusDays(1),5,9,5,true),e(today.minusDays(3),5,8,4,true));ok(RaceTraining.review(hard,today,false).factor()==.8,"repeated hard feedback");ok(RaceTraining.review(hard.stream().map(x->e(x.date(),x.km(),9,5,false)).toList(),today,false).factor()==1,"imported effort not inferred");
  var pain=List.of(new RaceTraining.Evidence(today,5,1800,4,2,true,true));ok(RaceTraining.review(pain,today,false).hold(),"pain blocks changes");ok(RaceTraining.review(List.of(),today,true).hold(),"existing hold honoured");
  for(double goal:new double[]{5,10,15,21.1,30,42.2})for(int weeks:new int[]{4,8,14,24}){
   LocalDate race=today.plusWeeks(weeks);var plan=RaceTraining.draft(today,race,goal,weeks,days,DayOfWeek.SUNDAY,20,PaceProfile.unset(),List.of(),false);
   ok(plan.sessions().size()==weeks*3,"complete schedule");Set<LocalDate> seen=new HashSet<>();
   for(var s:plan.sessions()){ok(!s.date().isBefore(today)&&s.date().isBefore(race)&&seen.add(s.date()),"date inside build and unique");ok(days.contains(s.date().getDayOfWeek()),"available day respected");if(!s.date().isBefore(race.minusDays(7)))ok(s.km()<=(s.date().isBefore(race.minusDays(2))?(goal<=10?2:4):1.5)&&!ScheduleProposer.demanding(s.title()),"race week limited");}
  }
  bad(()->RaceTraining.draft(today,today.plusDays(20),21.1,4,days,DayOfWeek.SUNDAY,12,PaceProfile.unset(),old,false),"short race never compresses");bad(()->RaceTraining.draft(today,today.plusWeeks(8),56,8,days,DayOfWeek.SUNDAY,12,PaceProfile.unset(),old,false),"ultra unsupported");bad(()->RaceTraining.draft(today,today.plusWeeks(8),10,8,days,DayOfWeek.MONDAY,12,PaceProfile.unset(),old,false),"long day must be selected");
  var lower=RaceTraining.draft(today,today.plusWeeks(12),10,12,days,DayOfWeek.SUNDAY,30,PaceProfile.unset(),List.of(e(today.minusDays(2),8,4,2,true),e(today.minusDays(10),8,4,2,true),e(today.minusDays(20),8,4,2,true)),false);ok(lower.config().weeklyKm()==6,"recorded baseline caps high entry");
  var returning=RaceTraining.draft(today,today.plusWeeks(8),10,8,days,DayOfWeek.SUNDAY,12,PaceProfile.unset(),old,false);ok(returning.preferences().mode().equals("Return to running"),"inactivity chooses return programme");
  var pending=List.of(new PlanEngine.Session("0-0",today,"Easy run",5,""),new PlanEngine.Session("0-1",today.plusDays(2),"Tempo run",5,""),new PlanEngine.Session("0-2",today.plusDays(9),"Long run",10,""));var changes=RaceTraining.changes(pending,review,today);ok(changes.size()==1&&changes.get(0).km()<5,"only future next seven days changed");ok(RaceTraining.changes(pending,RaceTraining.review(pain,today,false),today).isEmpty(),"hold means no proposal");
  Context context=new Context(Files.createTempDirectory("rwun-race").toFile());RunStore store=new RunStore(context);store.createPlan(new PlanEngine.Config(8,3,12,10,today),PaceProfile.unset(),false);store.add(new RunStore.Run("history",today.minusDays(20).toString(),5,30));String before=store.proposalFingerprint();
  JSONObject metadata=new JSONObject().put("date",today.plusWeeks(8).toString()).put("km",10).put("name","My race").put("city","Cape Town").put("country","South Africa");JSONObject options=new JSONObject().put("mode",returning.preferences().mode()).put("weekdays",new JSONArray(List.of(2,4,7))).put("longDay",7);
  bad(()->store.createRacePlan("stale",returning.config(),PaceProfile.unset(),metadata,options,returning.sessions()),"stale create refused");ok(store.proposalFingerprint().equals(before),"failed preview leaves plan unchanged");
  store.createRacePlan(before,returning.config(),PaceProfile.unset(),metadata,options,returning.sessions());ok(store.v103().getJSONObject("race").getString("planId").equals(store.planId()),"target linked atomically");ok(store.runs().size()==1,"history retained");ok(store.plannedSessions().equals(returning.sessions()),"exact preview saved");RunStore.validatePreferences(store.backupPreferences());ok(true,"race metadata backup validates");
  String original=store.proposalFingerprint();store.correctTotals("history",6,1800);ok(!store.proposalFingerprint().equals(original),"performance corrections invalidate preview");
  var proposal=RaceTraining.changes(store.plannedSessions(),review,today);ok(!proposal.isEmpty(),"proposal available");String ticket="a".repeat(64);store.applyReviewedProposal(store.proposalFingerprint(),proposal,ticket);ok(store.v103().getString("raceReview").equals(ticket),"review receipt committed");bad(()->store.applyReviewedProposal(store.proposalFingerprint(),proposal,ticket),"same evidence cannot compound reduction");
  JSONArray races=new JSONObject(Files.readString(Path.of("app/src/main/res/raw/races.json"))).getJSONArray("races");RaceCatalogue.validate(races);ok(RaceCatalogue.search(races,"cape town","South Africa",10,today,today.plusYears(2)).size()==1,"name city country distance date filters");ok(RaceCatalogue.search(races,"zzzz","South Africa",0,today,today.plusYears(2)).isEmpty(),"empty search");JSONArray duplicate=new JSONArray().put(races.getJSONObject(0)).put(races.getJSONObject(0));bad(()->RaceCatalogue.validate(duplicate),"duplicate provider identities rejected");JSONObject corrupt=new JSONObject(races.getJSONObject(0).toString()).put("source","javascript:alert(1)");bad(()->RaceCatalogue.validate(new JSONArray().put(corrupt)),"untrusted source scheme rejected");
  JSONObject raceBefore=store.v103().getJSONObject("race");java.io.ByteArrayOutputStream backup=new java.io.ByteArrayOutputStream();BackupManager.exportTo(context,store,backup);Context restoredContext=new Context(Files.createTempDirectory("rwun-race-restore").toFile());RunStore restored=new RunStore(restoredContext);BackupManager.restoreFrom(restoredContext,restored,new java.io.ByteArrayInputStream(backup.toByteArray()));ok(restored.v103().getJSONObject("race").toString().equals(raceBefore.toString()),"selected race survives backup round trip");ok(restored.v103().getString("raceReview").equals(ticket),"applied evidence receipt survives backup");
  store.adapt(new AdaptiveCoach.Advice(.8,true,"Test hold"));String held=store.proposalFingerprint();store.createRacePlan(held,returning.config(),PaceProfile.unset(),metadata,options,returning.sessions());ok(store.resting(),"creating race plan never clears hold");
  String saved=store.proposalFingerprint();JSONObject mismatch=new JSONObject(metadata.toString()).put("km",21.1);bad(()->store.createRacePlan(saved,returning.config(),PaceProfile.unset(),mismatch,options,returning.sessions()),"inconsistent race and distance rejected");ok(saved.equals(store.proposalFingerprint()),"failed target creation is atomic");
  for(String mode:List.of("start","return","improve","general","distance")){
   var goal=RaceTraining.goalDraft(today,10,8,days,DayOfWeek.SUNDAY,12,PaceProfile.unset(),List.of(),false,mode);ok(goal.sessions().size()==24,"distance goal complete: "+mode);ok(goal.config().start().equals(today),"distance goal starts today");
   if(mode.equals("start")||mode.equals("return"))ok(goal.preferences().mode().equals("Return to running"),"beginner return programme");
  }
  var goal=RaceTraining.goalDraft(today,10,8,days,DayOfWeek.SUNDAY,12,PaceProfile.unset(),List.of(),false,"distance");JSONObject goalOptions=new JSONObject().put("mode",goal.preferences().mode()).put("weekdays",new JSONArray(List.of(2,4,7))).put("longDay",7);store.createGoalPlan(store.proposalFingerprint(),goal.config(),PaceProfile.unset(),goalOptions,goal.sessions());ok(!store.v103().has("race"),"distance plan removes stale target without fake event");ok(store.resting(),"distance goal preserves hold");
  System.out.println(n+" race planning/catalogue/storage assertions passed");
 }
}
